int sv6621_station_parse_mgmt(FAR const uint8_t *payload, size_t length,
                              FAR struct sv6621_station_mgmt_s *event)
{
  FAR const uint8_t *frame;
  uint16_t frame_control;
  uint16_t frame_length;

  if (payload == NULL || event == NULL ||
      length <
          SV6621_STATION_MGMT_HEADER_SIZE + SV6621_STATION_FRAME_HEADER_SIZE ||
      payload[0] == 0 || payload[1] > SV6621_BAND_5GHZ)
    {
      return -EINVAL;
    }

  frame_length = sv6621_station_get_le16(payload + 4);
  if (frame_length < SV6621_STATION_FRAME_HEADER_SIZE ||
      frame_length > length - SV6621_STATION_MGMT_HEADER_SIZE)
    {
      return -EPROTO;
    }

  frame = payload + SV6621_STATION_MGMT_HEADER_SIZE;

int sv6621_connection_build_association_ies(
    FAR const struct sv6621_scan_entry_s *entry,
    enum sv6621_security_e security, FAR uint8_t *ies, size_t capacity,
    FAR size_t *length)
{
  size_t input = 0;
  size_t output = 0;

  if (entry == NULL || ies == NULL || length == NULL || capacity == 0 ||
      entry->ie_length > SV6621_SCAN_IE_CAPACITY)
    {
      return -EINVAL;
    }

  if (security != SV6621_SECURITY_OPEN &&
      security != SV6621_SECURITY_WPA2_PSK &&
      security != SV6621_SECURITY_WPA2_WPA3_PSK &&
      security != SV6621_SECURITY_WPA3_SAE)
    {
      return -EINVAL;
    }

  while (input < entry->ie_length)
    {
      uint8_t id;
      uint8_t ie_length;
      size_t encoded_length;

      if (entry->ie_length - input < 2)
        {
          return -EPROTO;
        }

      id = entry->ies[input];
      ie_length = entry->ies[input + 1];
      encoded_length = (size_t)ie_length + 2;
      if (encoded_length > entry->ie_length - input)
        {
          return -EPROTO;
        }

      if (id == SV6621_CONNECTION_IE_SUPPORTED_RATES ||
          id == SV6621_CONNECTION_IE_EXT_SUPPORTED_RATES)
        {
          if (encoded_length > capacity - output)
            {
              return -ENOSPC;
            }

          memcpy(ies + output, entry->ies + input, encoded_length);
          output += encoded_length;
        }

      input += encoded_length;
    }

  if (security != SV6621_SECURITY_OPEN)
    {
      FAR const uint8_t *rsn = security == SV6621_SECURITY_WPA3_SAE
                                   ? g_sv6621_connection_rsn_sae_ccmp
                                   : g_sv6621_connection_rsn_psk_ccmp;
      size_t rsn_length = security == SV6621_SECURITY_WPA3_SAE
                              ? sizeof(g_sv6621_connection_rsn_sae_ccmp)
                              : sizeof(g_sv6621_connection_rsn_psk_ccmp);

      if (rsn_length > capacity - output)
        {
          return -ENOSPC;
        }

      memcpy(ies + output, rsn, rsn_length);
      output += rsn_length;
    }

  if (output == 0)
    {
      return -EPROTO;
    }

  *length = output;
  return 0;
}

