+
+static void sv6621_scan_trace_ies(FAR const struct sv6621_scan_entry_s *entry)
+{
+  static const size_t step = 26;
+  char line[2 * 26 + 1];
+  size_t limit;
+  size_t offset;
+
+  limit = entry->ie_length < 130 ? entry->ie_length : 130;
+  for (offset = 0; offset < limit; offset += step)
+    {
+      size_t count = limit - offset < step ? limit - offset : step;
+      size_t index;
+
+      for (index = 0; index < count; index++)
+        {
+          snprintf(line + 2 * index, sizeof(line) - 2 * index, "%02x",
+                   entry->ies[offset + index]);
+        }
+
+      line[2 * count] = '\0';
+      sv6621_trace("  ies[%u/%u]: %s\n", (unsigned int)offset,
+                   (unsigned int)entry->ie_length, line);
+    }
+}
