+/****************************************************************************
+ * Name: sv6621_scan_cache_explain
+ *
+ * Description:
+ *   Reports the cache lookups sv6621_scan_cache_find() would have to accept
+ *   for the request, together with every filter that rejects them, so a
+ *   -ENOENT from a connect names the property of the AP that disqualified it.
+ *
+ ****************************************************************************/
+
+static void
+sv6621_scan_cache_explain(FAR const struct sv6621_scan_cache_s *cache,
+                          FAR const struct sv6621_connect_s *request)
+{
+  unsigned int listed = 0;
+  unsigned int matched = 0;
+  size_t index;
+
+  sv6621_trace("cache: no match for \"%.*s\" len=%u security=%d channel=%u, "
+               "%u entries\n",
+               request->ssid_length, request->ssid, request->ssid_length,
+               request->security, request->channel,
+               (unsigned int)cache->count);
+
+  for (index = 0; index < cache->count; index++)
+    {
+      FAR const struct sv6621_scan_entry_s *entry = &cache->entries[index];
+      FAR const struct sv6621_bss_s *bss = &entry->bss;
+
+      if (request->ssid_length != 0 &&
+          (bss->ssid_length != request->ssid_length ||
+           memcmp(bss->ssid, request->ssid, request->ssid_length) != 0))
+        {
+          if (listed++ < 16)
+            {
+              sv6621_trace("cache[%u]: ch=%u rssi=%d sec=%d ssid=\"%.*s\"\n",
+                           (unsigned int)index, bss->channel, bss->signal_dbm,
+                           bss->security, bss->ssid_length, bss->ssid);
+            }
+
+          continue;
+        }
+
+      matched++;
+      sv6621_trace("cache[%u]: " SV6621_TRACE_MAC_FMT " ch=%u band=%d rssi=%d"
+                   " sec=%d rsn=%u grp=%02x ccmp=%u caps=%04x ht=%u/%u/%u"
+                   " vht=%u/%u sec_ok=%u supported=%u\n",
+                   (unsigned int)index, SV6621_TRACE_MAC_ARG(bss->bssid),
+                   bss->channel, bss->band, bss->signal_dbm, bss->security,
+                   entry->rsn_present, entry->rsn_group_cipher,
+                   entry->rsn_pairwise_ccmp, entry->rsn_capabilities,
+                   entry->ht_operation_present, entry->ht_primary_channel,
+                   entry->ht_secondary_offset, entry->vht_operation_present,
+                   entry->vht_channel_width,
+                   sv6621_scan_security_matches(request->security,
+                                                bss->security),
+                   sv6621_scan_connection_supported(request->security, entry));
+
+      if (matched <= 2)
+        {
+          sv6621_scan_trace_ies(entry);
+        }
+    }
+
+  sv6621_trace("cache: %u entries carry the requested ssid\n", matched);
+}
